test('createInvoice calculates NET30 due date', () => {
  const tests = [
    { issue: '2025-01-15', expected: '2025-02-14' },
    { issue: '2025-01-01', expected: '2025-01-31' },
    { issue: '2025-12-01', expected: '2025-12-31' },
  ];

  for (const { issue, expected } of tests) {
    const result = createInvoice({
      customerId: 'C-002',
      issueDate: issue,
      lines: [{ sku: 'LOGO-PACK', qty: 1 }],
      terms: 'NET30',
    });

    assert.equal(result.ok, true, `Should succeed for ${issue}`);
    assert.equal(result.value.dueDate, expected, `NET30 due date should be correct for ${issue}`);
  }
});

test('createInvoice calculates EOM due date for various months', () => {
  const tests = [
    { issue: '2025-01-15', expected: '2025-01-31' }, // Jan has 31 days
    { issue: '2025-02-15', expected: '2025-02-28' }, // Feb 2025 has 28 days
    { issue: '2024-02-15', expected: '2024-02-29' }, // Feb 2024 (leap year) has 29 days
    { issue: '2025-04-15', expected: '2025-04-30' }, // Apr has 30 days
    { issue: '2025-12-01', expected: '2025-12-31' }, // Dec has 31 days
  ];

  for (const { issue, expected } of tests) {
    const result = createInvoice({
      customerId: 'C-002',
      issueDate: issue,
      lines: [{ sku: 'LOGO-PACK', qty: 1 }],
      terms: 'EOM',
    });

    assert.equal(result.ok, true, `Should succeed for ${issue}`);
    assert.equal(result.value.dueDate, expected, `EOM due date should be end of month for ${issue}`);
  }
});

