test('applyVoucher adds voucher to draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const voucherResult = applyVoucher(result.value, {
    code: 'SUMMER2025',
    amount: 50000,
  });

  assert.equal(voucherResult.ok, true);
