test('applyVoucher fails with invalid amount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const tests = [
    { amount: 0, desc: 'zero' },
    { amount: -100, desc: 'negative' },
    { amount: 100.5, desc: 'non-integer' },
    { amount: '50000', desc: 'string' },
  ];

  for (const { amount, desc } of tests) {
    const voucherResult = applyVoucher(result.value, {
      code: 'TEST',
      amount,
    });

    assert.equal(voucherResult.ok, false, `Should fail for ${desc}`);
    assert.equal(voucherResult.error, 'AMOUNT_INVALID', `Should fail with AMOUNT_INVALID for ${desc}`);
  }
