test('invoiceTotals includes voucher', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  let invoice = result.value;
  const totalsWithoutVoucher = invoiceTotals(invoice);

  const voucherResult = applyVoucher(invoice, {
    code: 'SUMMER2025',
    amount: 50000,
  });

  const totalsWithVoucher = invoiceTotals(voucherResult.value);

  assert.equal(totalsWithVoucher.voucher, 50000);
  assert.equal(totalsWithVoucher.total, totalsWithoutVoucher.total - 50000);
});

test('invoiceTotals with discount, VAT, and voucher', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });

  let invoice = result.value;
  const voucherResult = applyVoucher(invoice, {
    code: 'SUMMER2025',
    amount: 20000,
  });

  const totals = invoiceTotals(voucherResult.value);

  // LOGO-PACK: 120000, 10% discount = 12000
  // After discount: 108000, VAT 21% = 22680
  // Total before voucher: 108000 + 22680 = 130680
  // After voucher: 130680 - 20000 = 110680
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 12000);
  assert.equal(totals.vat, 22680);
  assert.equal(totals.voucher, 20000);
  assert.equal(totals.total, 110680);
});

